import{_ as a,o as t,c as l,ac as i}from"./chunks/framework.B-3EzaJq.js";const m=JSON.parse('{"title":"中国共产党第十二届中央委员会第四次全体会议","description":"","frontmatter":{"prev":{"text":"中国共产党第十二届中央委员会第三次全体会议公报","link":"../3/"},"next":{"text":"六十四位老同志请求不再担任中国共产党中央委员会委员、候补委员致党的十二届四中全会的信","link":"./六十四位老同志请求不再担任中国共产党中央委员会委员、候补委员致党的十二届四中全会的信"}},"headers":[],"relativePath":"12/4/index.md","filePath":"12/4/index.md"}'),r={name:"12/4/index.md"};function n(o,e,_,h,s,d){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="中国共产党第十二届中央委员会第四次全体会议" tabindex="-1">中国共产党第十二届中央委员会第四次全体会议 <a class="header-anchor" href="#中国共产党第十二届中央委员会第四次全体会议" aria-label="Permalink to &quot;中国共产党第十二届中央委员会第四次全体会议&quot;">​</a></h1><p>1985年9月16日在北京举行。全会决定于1985年9月18日召开中国共产党全国代表会议，全会还讨论并原则通过了《中共中央关于制定国民经济和社会发展第七个五年计划的建议（草案）》，决定将这个文件提请中国共产党的全国代表会议审议。全会讨论确定了关于进一步实现中央领导机构成员新老合作和交替的原则。全会收到了叶剑英等一批老同志分别请求不再担任第十二届中央委员会委员和候补委员、中央顾问委员会委员、中央纪律检查委员会委员的信。全会高度评价这些老同志从党和人民利益出发，积极促进中央领导机构成员新老交替的表率行动，同意他们不再担任中央三个委员会成员的请求，并向中国共产党的全国代表会议报告。全会给叶剑英同志和黄克诚同志写了致敬信，在他们由于健康原因请求不再担任中央领导职务的时候，以全会的名义表达全党同志对他们的崇高敬意和亲切问候。</p><ul><li><a href="./六十四位老同志请求不再担任中国共产党中央委员会委员、候补委员致党的十二届四中全会的信.html">六十四位老同志请求不再担任中国共产党中央委员会委员、候补委员致党的十二届四中全会的信</a></li><li><a href="./三十七位老同志请求不再担任中国共产党中央顾问委员会委员致党的十二届四中全会的信.html">三十七位老同志请求不再担任中国共产党中央顾问委员会委员致党的十二届四中全会的信</a></li><li><a href="./三十位老同志请求不再担任中国共产党中央纪律检查委员会委员致党的十二届四中全会的信.html">三十位老同志请求不再担任中国共产党中央纪律检查委员会委员致党的十二届四中全会的信</a></li><li><a href="./中国共产党十二届四中全会给叶剑英同志的致敬信.html">中国共产党十二届四中全会给叶剑英同志的致敬信</a></li><li><a href="./中国共产党十二届四中全会给黄克诚同志的致敬信.html">中国共产党十二届四中全会给黄克诚同志的致敬信</a></li><li><a href="./中国共产党第十二届中央委员会第四次全体会议公报.html">中国共产党第十二届中央委员会第四次全体会议公报</a></li></ul>',3)])])}const f=a(r,[["render",n]]);export{m as __pageData,f as default};
